private fun render(state: LabUiState, adapter: DeviceAdapter) = trace("DeviceListFragment.render") {
    binding.loading.isVisible = state.isLoading
    adapter.unit = state.unit
    adapter.submitList(state.visibleDevices) // DiffUtil chạy nền, chỉ dòng đổi mới được bind lại

    val showEmpty = !state.isLoading && state.visibleDevices.isEmpty()
    if (showEmpty && emptyView == null) emptyView = binding.emptyStub.inflate()
    emptyView?.isVisible = showEmpty

    val wanted = state.floorFilter ?: ALL_FLOORS
    val chip = binding.floorChips.children.firstOrNull { it.tag == wanted }
    if (chip != null && binding.floorChips.checkedChipId != chip.id) binding.floorChips.check(chip.id)
}

